use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigRetryDelayAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigRetryDelayAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigRetryDelayAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRetryDelay returns null on a freshly created holder.
     */
    public function testRetryDelayNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigRetryDelayAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRetryDelayAssigned());
        $this->assertNull($holder->getRetryDelay());
    }
}
class ImplWithSmtpOutboundConfigRetryDelayAttributeHolderUnitTest
{
    use SmtpOutboundConfigRetryDelayAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRetryDelayRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRetryDelay();
    }
}
